

CREATE VIEW [dbo].[FP_SIMULATION_CELL_V]
-- ================================================================================================
-- Program ID          : FP_SIMULATION_CELL_V
--
-- Program Name        : FP_SIMULATION_CELL_V
-- Param               :
-- Batch Period        : 
-- Description         : Excel Simulation용 View
--
-- Source System       : FP SDB
-- Destination System  : FP SDB
-- Source Table        : FP_AMEND_PLAN_CELL_R
-- Destination Table   : FP_AMEND_PLAN_CELL_R
--
-- Create(Update) Date : 2021.04.22
-- Author              : park Seongyong
-- Version             : 2019-07-26 piyong 신규 생성
--                       2019-08-16 kimcd  속도 개선 작업
--                       2019-09-03 kimcd  WPP 차질 정보, 동, Model, Item별 예상 재고 추가
--                       2019-09-10 kimcd  MPP, In, UOM 수량 제외
--                       2019-09-16 kimcd  Plan UOM은 유지. Cell 기반 BOH 컬럼 추가
--                       2019-09-26 kimcd  WPP 0보다 크다 조건 추가
--                       2021-04-22 kimcd  Demand Type lookup 제약 추가
-- ================================================================================================
AS 
	WITH DA AS ( SELECT S.SITE_ID
	               , D.DATE_ID
				   , RANK() OVER (PARTITION BY S.SITE_ID ORDER BY D.DATE_ID) NUM
			  FROM   [dbo].[SCM_SYS_CALENDAR_M] D WITH(NOLOCK)
				   , (SELECT S.SITE_ID
					  FROM   SCM_SITE_M S WITH(NOLOCK)
					  GROUP  BY S.SITE_ID) S
		      WHERE  D.DATE_ID >= CONVERT(DATE, DATEADD(D, -DAY(DBO.FN_SITE_TIME(S.SITE_ID) - 1), DBO.FN_SITE_TIME(S.SITE_ID)))
		      AND    D.DATE_ID <= DATEADD( D, 99,CONVERT(DATE, DATEADD(D, -DAY(DBO.FN_SITE_TIME(S.SITE_ID) - 1), DBO.FN_SITE_TIME(S.SITE_ID)))) ) 
	, MAIN_S AS (
		SELECT A.INSTANCE_ID
			   , A.FP_PLAN_ID
			   , A.COMPANY_ID
			   , A.DIVISION_ID
			   , A.SITE_ID
			   , A.PLANT_ID
			   , A.TOP_ITEM_ID
			   , A.ITEM_ID
			   , B.ITEM_TYPE
			   , ISNULL(C.NICK_NAME,'-') AS NICK_NAME
               , A.OPERATION_ID
               , A.FACTORY_ID, A.LOCATION
               , ISNULL(D.QTY,0) AS BOH_QTY
               , A.PRODUCTION_TYPE, A.MARKET
               , A.PSI
               , A.LINE_ID
               , NULL AS LINE_NAME
               , A.ELECTRODE_TYPE
               , A.CATE
               , A.D1
               , A.D2
               , A.D3
               , A.D4
               , A.D5
               , A.D6
               , A.D7
               , A.D8
               , A.D9
               , A.D10
               , A.D11
               , A.D12
               , A.D13
               , A.D14
               , A.D15
               , A.D16
               , A.D17
               , A.D18
               , A.D19
               , A.D20
               , A.D21
               , A.D22
               , A.D23
               , A.D24
               , A.D25
               , A.D26
               , A.D27
               , A.D28
               , A.D29
               , A.D30
               , A.D31
               , A.D32
               , A.D33
               , A.D34
               , A.D35
               , A.D36
               , A.D37
               , A.D38
               , A.D39
               , A.D40
               , A.D41
               , A.D42
               , A.D43
               , A.D44
               , A.D45
               , A.D46
               , A.D47
               , A.D48
               , A.D49
               , A.D50
               , A.D51
               , A.D52
               , A.D53
               , A.D54
               , A.D55
               , A.D56
               , A.D57
               , A.D58
               , A.D59
               , A.D60
               , A.D61
               , A.D62
               , A.D63
               , A.D64
               , A.D65
               , A.D66
               , A.D67
               , A.D68
               , A.D69
               , A.D70
               , A.D71
               , A.D72
               , A.D73
               , A.D74
               , A.D75
               , A.D76
               , A.D77
               , A.D78
               , A.D79
               , A.D80
               , A.D81
               , A.D82
               , A.D83
               , A.D84
               , A.D85
               , A.D86
               , A.D87
               , A.D88
               , A.D89
               , A.D90
               , A.D91
               , A.D92
               , A.D93
               , A.D94
               , A.D95
               , A.D96
               , A.D97
               , A.D98
               , A.D99
               , A.D100
			   , A.CATEGORY_ID
			   , A.CATEGORY_ORDER
               , '' AS MEASURE_ID
			   , '' AS MEASURE_NAME
               , A.S_ROW
          FROM (
				SELECT A.INSTANCE_ID
						, A.FP_PLAN_ID
					   ,A.COMPANY_ID
					   , A.DIVISION_ID
					   , A.SITE_ID
					   , A.PLANT_ID
					   , A.TOP_ITEM_ID
					   , A.ITEM_ID
					   , A.ITEM_TYPE
		               , A.OPERATION_ID
		               , A.FACTORY_ID
					   , A.LOCATION
		               , A.PRODUCTION_TYPE, A.MARKET
		               , 'S' AS PSI
		               , NULL AS LINE_ID
		               , NULL AS ELECTRODE_TYPE
		               , B.CATEGORY_NAME AS CATE           
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 1 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D1
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 2 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D2
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 3 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D3
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 4 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D4
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 5 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D5
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 6 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D6
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 7 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D7
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 8 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D8
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 9 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D9
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 10 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D10
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 11 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D11
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 12 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D12
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 13 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D13
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 14 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D14
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 15 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D15
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 16 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D16
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 17 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D17
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 18 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D18
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 19 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D19
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 20 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D20
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 21 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D21
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 22 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D22
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 23 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D23
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 24 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D24
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 25 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D25
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 26 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D26
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 27 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D27
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 28 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D28
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 29 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D29
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 30 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D30
