					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 32 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D32
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 33 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D33
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 34 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D34
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 35 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D35
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 36 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D36
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 37 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D37
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 38 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D38
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 39 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D39
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 40 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D40
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 41 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D41
