					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 50 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D50
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 51 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D51
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 52 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D52
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 53 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D53
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 54 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D54
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 55 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D55
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 56 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D56
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 57 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D57
