					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 75 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D75
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 76 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D76
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 77 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D77
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 78 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D78
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 79 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D79
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 80 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D80
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 81 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D81
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 82 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D82
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 83 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D83
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 84 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D84
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 85 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D85
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 86 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D86
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 87 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D87
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 88 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D88
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 89 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D89
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 90 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D90
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 91 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D91
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 92 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D92
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 93 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D93
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 94 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D94
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 95 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D95
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 96 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D96
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 97 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D97
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 98 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D98
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 99 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D99
					   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 100 THEN (CASE WHEN B.CATEGORY_ID='S' THEN A.SALES_QTY ELSE A.PAST_SALES_QTY END) ELSE 0 END) AS D100
		               , B.CATEGORY_ID
					   , B.CATEGORY_ORDER
		               , ROW_NUMBER() OVER( PARTITION BY A.INSTANCE_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.TOP_ITEM_ID, A.ITEM_ID, A.OPERATION_ID, A.FACTORY_ID, A.LOCATION
		                                        ORDER BY A.INSTANCE_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.TOP_ITEM_ID, A.ITEM_ID, A.OPERATION_ID, A.FACTORY_ID, A.LOCATION, A.PRODUCTION_TYPE, A.MARKET, B.CATEGORY_ORDER) AS S_ROW
	              FROM (
				        SELECT A.INSTANCE_ID
							   , A.FP_PLAN_ID
				               , A.COMPANY_ID
							   , A.DIVISION_ID
							   , A.SITE_ID
							   , A.PLANT_ID
					           , A.TOP_ITEM_ID, A.ITEM_ID, NULL ITEM_TYPE
				               , A.OPERATION_ID
							   , A.FACTORY_ID, A.LOCATION
							   , NULL AS BOH_QTY
							   , A.PRODUCTION_TYPE, A.MARKET
							   , 'S' AS PSI
							   , A.LINE_ID
							   , A.ELECTRODE_TYPE
							   , A.PLAN_DATE
							   , A.SALES_QTY
							   , A.PAST_SALES_QTY
				          FROM FP_AMEND_PLAN_CELL_SALES_R A WITH(NOLOCK)
				         WHERE ( ISNULL(A.SALES_QTY,0) > 0 OR ISNULL(A.PAST_SALES_QTY,0) > 0)
				        UNION ALL
				        SELECT A.INSTANCE_ID
								, A.FP_PLAN_ID
								, A.COMPANY_ID
								, A.DIVISION_ID
								, A.SITE_ID
								, A.PLANT_ID
								, A.TOP_ITEM_ID, A.ITEM_ID, NULL ITEM_TYPE
								, A.OPERATION_ID
								, A.FACTORY_ID, A.LOCATION
								, NULL AS BOH_QTY
								, A.PRODUCTION_TYPE, A.MARKET
								, 'S' AS PSI
								, A.LINE_ID
								, A.ELECTRODE_TYPE
								, A.PLAN_DATE
								, 0 AS SALES_QTY
								, 0 AS PAST_SALES_QTY
							FROM FP_AMEND_PLAN_CELL_R A WITH(NOLOCK)
							    ,SCM_SYS_LOOKUP_VALUE SLV WITH(NOLOCK)  -- 2021-04-22 kimcd production type 조건 추가
							WHERE( A.OUT_QTY <> 0 OR A.RESULT_OUT_QTY <> 0 OR A.WPP_OUT_QTY <> 0 ) -- 2019-09-26 kimcd "OR A.WPP_OUT_QTY <> 0"  조건 추가
							AND  A.DIVISION_ID = SLV.SEGMENT1
							AND  A.PRODUCTION_TYPE = SLV.ATTRIBUTE2
							AND  SLV.LOOKUP_TYPE_CODE = 'DIVISION_DEMAND_TYPE'
							AND  SLV.ACTIVE_FLAG = 'Y'
					   ) A
					   INNER JOIN (
                					SELECT 'S' AS CATEGORY_ID, 'S' AS CATEGORY_NAME, 10 AS CATEGORY_ORDER
                					UNION ALL
                					SELECT 'PAST_SALES' AS CATEGORY_ID, 'S(W-1)' AS CATEGORY_NAME, 20 AS CATEGORY_ORDER
			    	              ) B
    						   ON 1=1
					   INNER JOIN DA DA
							   ON  A.SITE_ID   = DA.SITE_ID
							   AND A.PLAN_DATE = DA.DATE_ID
			     GROUP BY A.INSTANCE_ID
					   , A.FP_PLAN_ID
					   , A.COMPANY_ID
					   , A.DIVISION_ID
					   , A.SITE_ID
					   , A.PLANT_ID
			           , A.TOP_ITEM_ID
					   , A.ITEM_ID
					   , A.ITEM_TYPE
			           , A.OPERATION_ID
			           , A.FACTORY_ID
					   , A.LOCATION
			           , A.PRODUCTION_TYPE
					   , A.MARKET
			           , B.CATEGORY_ID
					   , B.CATEGORY_NAME
					   , B.CATEGORY_ORDER
			   ) A
			   INNER JOIN (
							SELECT   A.COMPANY_ID
								   , A.DIVISION_ID
								   , A.SITE_ID
								   , A.ITEM_ID
								   , (CASE WHEN LEFT(A.FLOW_ID,5) = 'A9000' AND ISNULL(C.LEVEL_4_NAME, '-') = '-' THEN C.LEVEL_3_NAME
                     					   WHEN LEFT(A.FLOW_ID,5) = 'A9000' THEN ISNULL(C.LEVEL_4_NAME, '-')
                     					   ELSE C.LEVEL_3_NAME END) AS ITEM_TYPE
							  FROM SCM_ITEM_M A WITH(NOLOCK)
								   , SCM_ITEM_CLASS_M C WITH(NOLOCK)
							 WHERE A.ITEM_CLASS  = C.CLASS_ID
					      ) B
					   ON A.COMPANY_ID  = B.COMPANY_ID
					  AND A.DIVISION_ID = B.DIVISION_ID
					  AND A.SITE_ID     = B.SITE_ID
					  AND A.ITEM_ID     = B.ITEM_ID
			   INNER JOIN SCM_ITEM_M C WITH(NOLOCK)
					   ON A.COMPANY_ID   = C.COMPANY_ID
					  AND A.DIVISION_ID  = C.DIVISION_ID
					  AND A.SITE_ID      = C.SITE_ID
					  AND A.TOP_ITEM_ID  = C.ITEM_ID
			   LEFT OUTER JOIN (	
								SELECT   A.INSTANCE_ID   -- 2019-08-16 kimcd 튜닝 추가
								       , A.FP_PLAN_ID
									   , A.COMPANY_ID
									   , A.DIVISION_ID
									   , A.SITE_ID
									   , A.PLANT_ID
									   , A.FACTORY_ID
									   , A.OPERATION_ID
									   , A.LOCATION
									   , A.ITEM_ID
									   , A.TOP_ITEM_ID
                     --, FLOOR(SUM(ISNULL(A.MODIFY_QTY, A.QTY))  * ISNULL(DBO.FN_GET_REQ_QTY_MODEL(A.PLANT_ID, A.TOP_ITEM_ID, A.ITEM_ID, SUBSTRING(REPLACE(A.FP_PLAN_ID , A.INSTANCE_ID , '') , 2,8)),1))	AS QTY  -- 2019-09-19 songhs Cell 환산 로직추가 
									    , SUM(ISNULL(A.MODIFY_QTY, A.QTY)) AS QTY
					              FROM FP_AMEND_CUTOFF_BOH_R A WITH(NOLOCK)
								  GROUP BY A.INSTANCE_ID   -- 2019-08-16 kimcd 튜닝 추가
								        , A.FP_PLAN_ID
										, A.COMPANY_ID
										, A.DIVISION_ID
										, A.SITE_ID
										, A.PLANT_ID
										, A.FACTORY_ID
										, A.OPERATION_ID
										, A.LOCATION
										, A.ITEM_ID
										, A.TOP_ITEM_ID
							   ) D
						    ON A.INSTANCE_ID  = D.INSTANCE_ID  -- 2019-08-16 kimcd 튜닝 추가
						   AND A.FP_PLAN_ID   = D.FP_PLAN_ID
						   AND A.COMPANY_ID   = D.COMPANY_ID
						   AND A.DIVISION_ID  = D.DIVISION_ID
						   AND A.SITE_ID      = D.SITE_ID
						   AND A.PLANT_ID     = D.PLANT_ID
						   AND A.FACTORY_ID   = D.FACTORY_ID
						   AND A.OPERATION_ID = D.OPERATION_ID
						   AND A.LOCATION     = D.LOCATION
						   AND A.ITEM_ID      = D.ITEM_ID
						   AND A.TOP_ITEM_ID  = D.TOP_ITEM_ID
      )
      , MAIN_P AS (
          -- P : builing, location, production type, market, line
					SELECT A.INSTANCE_ID
						   , A.FP_PLAN_ID
						   , A.COMPANY_ID
						   , A.DIVISION_ID
						   , A.SITE_ID
						   , A.PLANT_ID
						   , A.TOP_ITEM_ID
						   , A.ITEM_ID
						   , A.ITEM_TYPE
						   , A.NICK_NAME
						   , A.OPERATION_ID
						   , A.FACTORY_ID, A.LOCATION
						   , ISNULL(MAX(F.QTY),0) AS BOH_QTY
						   , A.PRODUCTION_TYPE
						   , A.MARKET
						   , 'P' AS PSI
						   , A.LINE_ID
						   , A.LINE_NAME
						   , A.ELECTRODE_TYPE
						   , D.CATE_NAME AS CATE	            
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 1 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D1 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 2 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0) 
																		ELSE 0 END ) ELSE 0 END) AS D2 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 3 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D3 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 4 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D4 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 5 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D5 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 6 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
