																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D96 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 97 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D97 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 98 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D98 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 99 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D99 
						   , SUM(CASE WHEN CONVERT(VARCHAR,A.PLAN_DATE,112) = DA.DATE_ID AND DA.NUM = 100 THEN (CASE WHEN D.CATE_ID = 'M_IN_CELL' THEN ROUND(A.MPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'M_IN' THEN A.MPP_IN_QTY 
																		WHEN D.CATE_ID = 'M_OUT_CELL' THEN ROUND(A.MPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'M_OUT' THEN A.MPP_OUT_QTY 
																		WHEN D.CATE_ID = 'W_IN_CELL' THEN ROUND(A.WPP_CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'W_IN' THEN A.WPP_IN_QTY 
																		WHEN D.CATE_ID = 'W_OUT_CELL' THEN ROUND(A.WPP_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'W_OUT' THEN A.WPP_OUT_QTY 
																		WHEN D.CATE_ID = 'P_IN_CELL' THEN ROUND(A.CELL_IN_QTY,0) 
																		WHEN D.CATE_ID = 'P_IN' THEN A.IN_QTY 
																		WHEN D.CATE_ID = 'P_OUT_CELL' THEN ROUND(A.CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_OUT' THEN A.OUT_QTY 
																		WHEN D.CATE_ID = 'P_RESULT_CELL' THEN ROUND(A.RESULT_CELL_OUT_QTY,0) 
																		WHEN D.CATE_ID = 'P_RESULT' THEN ROUND(A.RESULT_OUT_QTY,0)
																		ELSE 0 END ) ELSE 0 END) AS D100
 						   , D.CATE_ID AS CATEGORY_ID
						   , D.CATE_ORDER AS CATEGORY_ORDER
						   , D.MEASURE_ID
						   , D.MEASURE_NAME
						   , NULL AS S_ROW
					  FROM (
							 SELECT A.INSTANCE_ID
								    , A.FP_PLAN_ID
  									, A.COMPANY_ID
  									, A.DIVISION_ID
  									, A.SITE_ID
  									, A.PLANT_ID
  									, A.TOP_ITEM_ID
  									, A.ITEM_ID
  									, B.ITEM_TYPE
  									, A.OPERATION_ID
  									, A.FACTORY_ID
  									, A.LOCATION
  									, A.BOH_QTY
  									, A.PRODUCTION_TYPE
  									, A.MARKET
  									, A.PSI
  									, A.LINE_ID
  									, A.ELECTRODE_TYPE
  									, A.PLAN_DATE
  									, ISNULL(C.NICK_NAME,'-') AS NICK_NAME
  									, ISNULL(E.LINE_NAME,'-') AS LINE_NAME
  									, A.IN_QTY
  									, A.OUT_QTY
  									, A.CELL_IN_QTY
  									, A.CELL_OUT_QTY
  									, A.MPP_IN_QTY
  									, A.MPP_CELL_IN_QTY
  									, A.MPP_OUT_QTY
  									, A.MPP_CELL_OUT_QTY
  									, A.WPP_IN_QTY
  									, A.WPP_CELL_IN_QTY
  									, A.WPP_OUT_QTY
  									, A.WPP_CELL_OUT_QTY
  									, A.RESULT_CELL_OUT_QTY
  									, A.RESULT_OUT_QTY
							   FROM (
										SELECT A.INSTANCE_ID
											   , A.FP_PLAN_ID
											   , A.COMPANY_ID
											   , A.DIVISION_ID
											   , A.SITE_ID
											   , A.PLANT_ID
											   , A.TOP_ITEM_ID
											   , A.ITEM_ID
											   , NULL ITEM_TYPE
											   , A.OPERATION_ID
											   , A.FACTORY_ID, A.LOCATION
											   , NULL AS BOH_QTY
											   , A.PRODUCTION_TYPE, A.MARKET
											   , 'P' AS PSI
											   , A.LINE_ID
											   , A.ELECTRODE_TYPE
											   , A.PLAN_DATE 
											   , A.IN_QTY
											   , A.OUT_QTY
											   , A.CELL_IN_QTY
											   , A.CELL_OUT_QTY
											   , A.MPP_IN_QTY
											   , A.MPP_CELL_IN_QTY
											   , A.MPP_OUT_QTY
											   , A.MPP_CELL_OUT_QTY
											   , A.WPP_IN_QTY
											   , A.WPP_CELL_IN_QTY
											   , A.WPP_OUT_QTY
											   , A.WPP_CELL_OUT_QTY
											   , A.RESULT_CELL_OUT_QTY
											   , A.RESULT_OUT_QTY AS RESULT_OUT_QTY
										  FROM FP_AMEND_PLAN_CELL_R A WITH(NOLOCK)
											  ,SCM_SYS_LOOKUP_VALUE SLV WITH(NOLOCK)  -- 2021-04-22 kimcd production type 조건 추가
										 WHERE ( A.OUT_QTY <> 0 OR A.RESULT_OUT_QTY <> 0 OR A.WPP_OUT_QTY <> 0 ) -- 2019-09-26 kimcd "OR A.WPP_OUT_QTY <> 0"  조건 추가
										 AND  A.DIVISION_ID = SLV.SEGMENT1
										 AND  A.PRODUCTION_TYPE = SLV.ATTRIBUTE2
										 AND  SLV.LOOKUP_TYPE_CODE = 'DIVISION_DEMAND_TYPE'
										 AND  SLV.ACTIVE_FLAG = 'Y'
									  ) A
									  INNER JOIN (  SELECT   A.COMPANY_ID
														   , A.DIVISION_ID
														   , A.SITE_ID
														   , A.ITEM_ID
														   , ( CASE WHEN LEFT(A.FLOW_ID,5) = 'A9000' AND ISNULL(C.LEVEL_4_NAME, '-') = '-' THEN C.LEVEL_3_NAME
				                       								WHEN LEFT(A.FLOW_ID,5) = 'A9000' THEN ISNULL(C.LEVEL_4_NAME, '-')
				                       								ELSE C.LEVEL_3_NAME END
															  ) AS ITEM_TYPE
													  FROM SCM_ITEM_M A WITH(NOLOCK),
				                  						   SCM_ITEM_CLASS_M C WITH(NOLOCK)
													 WHERE A.ITEM_CLASS  = C.CLASS_ID
												 ) B
												 ON A.COMPANY_ID  = B.COMPANY_ID
												AND A.DIVISION_ID = B.DIVISION_ID
												AND A.SITE_ID     = B.SITE_ID
												AND A.ITEM_ID     = B.ITEM_ID
									  INNER JOIN SCM_ITEM_M C WITH(NOLOCK)
											  ON A.COMPANY_ID   = C.COMPANY_ID
											 AND A.DIVISION_ID  = C.DIVISION_ID
											 AND A.SITE_ID      = C.SITE_ID
											 AND A.TOP_ITEM_ID  = C.ITEM_ID
									  INNER JOIN SCM_LINE_M E WITH(NOLOCK)
											  ON A.COMPANY_ID     = E.COMPANY_ID
											 AND A.DIVISION_ID    = E.DIVISION_ID
											 AND A.SITE_ID        = E.SITE_ID
											 AND A.PLANT_ID       = E.PLANT_ID
											 AND A.FACTORY_ID     = E.FACTORY_ID
											 AND A.OPERATION_ID   = E.OPERATION_ID
											 AND A.LINE_ID        = E.LINE_ID
											 AND A.ELECTRODE_TYPE = E.ELECTRODE_TYPE
						   ) A
						   INNER JOIN ( -- 2019-09-10 kimcd  MPP, In 수량 제외 수정 시작
										  --SELECT 21 AS CATE_ORDER, 'MPP(In)' AS CATE_NAME, 'M_IN_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 23 AS CATE_ORDER, 'MPP(In)' AS CATE_NAME, 'M_IN' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 26 AS CATE_ORDER, 'MPP(Out)' AS CATE_NAME, 'M_OUT_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 29 AS CATE_ORDER, 'MPP(Out)' AS CATE_NAME, 'M_OUT' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 32 AS CATE_ORDER, 'WPP(In)' AS CATE_NAME, 'W_IN_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 35 AS CATE_ORDER, 'WPP(In)' AS CATE_NAME, 'W_IN' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  --UNION ALL
										  SELECT 38 AS CATE_ORDER, 'WPP(Out)' AS CATE_NAME, 'W_OUT_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 41 AS CATE_ORDER, 'WPP(Out)' AS CATE_NAME, 'W_OUT' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 44 AS CATE_ORDER, 'Plan(In)' AS CATE_NAME, 'P_IN_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 47 AS CATE_ORDER, 'Plan(In)' AS CATE_NAME, 'P_IN' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  UNION ALL
										  SELECT 50 AS CATE_ORDER, 'Plan(Out)' AS CATE_NAME, 'P_OUT_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  UNION ALL
										  SELECT 53 AS CATE_ORDER, 'Plan(Out)' AS CATE_NAME, 'P_OUT' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  UNION ALL
										  SELECT 56 AS CATE_ORDER, 'Result' AS CATE_NAME, 'P_RESULT_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  UNION ALL
										  SELECT 59 AS CATE_ORDER, 'Result' AS CATE_NAME, 'P_RESULT' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  -- 2019-09-03 kimcd add start
										  UNION ALL
										  SELECT 60 AS CATE_ORDER, 'WPP GAP' AS CATE_NAME, 'P_WPP_GAP_CELL' AS CATE_ID, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
										  --UNION ALL
										  --SELECT 61 AS CATE_ORDER, 'WPP GAP' AS CATE_NAME, 'P_WPP_GAP' AS CATE_ID, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
										  -- 2019-09-03 kimcd add end
										  -- 2019-09-10 kimcd  MPP, In 수량 제외 수정 종료
										  UNION ALL
										  SELECT 65 AS CATE_ORDER, 'Yield' AS CATE_NAME, 'Yield' AS CATE_ID, '' AS MEASURE_ID, '' AS MEASURE_NAME
										  UNION ALL
										  SELECT 75 AS CATE_ORDER, 'Conversion' AS CATE_NAME, 'Conversion' AS CATE_ID, '' AS MEASURE_ID, '' AS MEASURE_NAME
									  ) D
								   ON 1=1
						   LEFT OUTER JOIN (
											SELECT    A.INSTANCE_ID   -- 2019-08-16 kimcd 튜닝 추가
											        , A.FP_PLAN_ID
													, A.COMPANY_ID
													, A.DIVISION_ID
													, A.SITE_ID
													, A.PLANT_ID
													, A.FACTORY_ID 
													, A.OPERATION_ID
													, A.LOCATION
													, A.ITEM_ID
													, A.TOP_ITEM_ID
                          , SUM(ISNULL(A.MODIFY_QTY, A.QTY)) AS QTY
													--, FLOOR(SUM(ISNULL(A.MODIFY_QTY, A.QTY))  * ISNULL(DBO.FN_GET_REQ_QTY_MODEL(A.PLANT_ID, A.TOP_ITEM_ID, A.ITEM_ID, SUBSTRING(REPLACE(A.FP_PLAN_ID , A.INSTANCE_ID , '') , 2,8)),1))		AS QTY -- 2019-09-19 songhs Cell 환산 로직추가 
											  FROM FP_AMEND_CUTOFF_BOH_R A WITH(NOLOCK)
											  GROUP BY A.INSTANCE_ID  -- 2019-08-16 kimcd 튜닝 추가 
											        , A.FP_PLAN_ID
													, A.COMPANY_ID
													, A.DIVISION_ID
													, A.SITE_ID
													, A.PLANT_ID
													, A.FACTORY_ID
													, A.OPERATION_ID
													, A.LOCATION
													, A.ITEM_ID
													, A.TOP_ITEM_ID
										   ) F
										ON A.INSTANCE_ID  = A.INSTANCE_ID  -- 2019-08-16 kimcd 튜닝 추가
									   AND A.FP_PLAN_ID	  = F.FP_PLAN_ID
									   AND A.COMPANY_ID   = F.COMPANY_ID
									   AND A.DIVISION_ID  = F.DIVISION_ID
									   AND A.SITE_ID      = F.SITE_ID
									   AND A.PLANT_ID     = F.PLANT_ID
									   AND A.FACTORY_ID   = F.FACTORY_ID
									   AND A.OPERATION_ID = F.OPERATION_ID
									   AND A.LOCATION     = F.LOCATION
									   AND A.ITEM_ID      = F.ITEM_ID
									   AND A.TOP_ITEM_ID  = F.TOP_ITEM_ID
						   INNER JOIN DA  DA
								  ON  A.SITE_ID  = DA.SITE_ID
								  AND A.PLAN_DATE = DA.DATE_ID
					 GROUP BY A.INSTANCE_ID
							, A.FP_PLAN_ID
							, A.COMPANY_ID
							, A.DIVISION_ID
							, A.SITE_ID
							, A.PLANT_ID
							, A.TOP_ITEM_ID
							, A.ITEM_ID
							, A.ITEM_TYPE
							, A.NICK_NAME
							, A.OPERATION_ID
							, A.FACTORY_ID
							, A.LOCATION
							, A.PRODUCTION_TYPE
							, A.MARKET
							, A.LINE_ID
							, A.LINE_NAME
							, A.ELECTRODE_TYPE
							, D.CATE_NAME
							, D.CATE_ORDER
							, D.CATE_NAME
							, D.CATE_ID
							, D.MEASURE_ID
							, D.MEASURE_NAME
				  )
	    -- 2019-09-93 kimcd add start
      ,  MAIN_I AS (
          SELECT A.INSTANCE_ID, A.FP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID
               , A.TOP_ITEM_ID, A.ITEM_ID, A.ITEM_TYPE, MAX(A.NICK_NAME) AS NICK_NAME
               , A.OPERATION_ID
               , A.FACTORY_ID, A.LOCATION
               , ISNULL(MAX(A.QTY),0) AS BOH_QTY
               , NULL AS PRODUCTION_TYPE
               , NULL AS MARKET
               , 'I' AS PSI
               , NULL AS LINE_ID
               , NULL AS LINE_NAME
               , NULL AS ELECTRODE_TYPE
               , B.CATEGORY_NAME AS CATE
			   , 0 AS D1
			   , 0 AS D2
			   , 0 AS D3
			   , 0 AS D4
			   , 0 AS D5
			   , 0 AS D6
			   , 0 AS D7
			   , 0 AS D8
			   , 0 AS D9
			   , 0 AS D10
			   , 0 AS D11
			   , 0 AS D12
			   , 0 AS D13
			   , 0 AS D14
			   , 0 AS D15
			   , 0 AS D16
			   , 0 AS D17
			   , 0 AS D18
			   , 0 AS D19
			   , 0 AS D20
			   , 0 AS D21
			   , 0 AS D22
			   , 0 AS D23
			   , 0 AS D24
			   , 0 AS D25
			   , 0 AS D26
			   , 0 AS D27
			   , 0 AS D28
			   , 0 AS D29
			   , 0 AS D30
			   , 0 AS D31
			   , 0 AS D32
			   , 0 AS D33
			   , 0 AS D34
			   , 0 AS D35
			   , 0 AS D36
			   , 0 AS D37
			   , 0 AS D38
			   , 0 AS D39
			   , 0 AS D40
			   , 0 AS D41
			   , 0 AS D42
			   , 0 AS D43
			   , 0 AS D44
			   , 0 AS D45
			   , 0 AS D46
			   , 0 AS D47
			   , 0 AS D48
			   , 0 AS D49
			   , 0 AS D50
			   , 0 AS D51
			   , 0 AS D52
			   , 0 AS D53
			   , 0 AS D54
			   , 0 AS D55
			   , 0 AS D56
			   , 0 AS D57
			   , 0 AS D58
			   , 0 AS D59
			   , 0 AS D60
			   , 0 AS D61
			   , 0 AS D62
			   , 0 AS D63
			   , 0 AS D64
			   , 0 AS D65
			   , 0 AS D66
			   , 0 AS D67
			   , 0 AS D68
			   , 0 AS D69
			   , 0 AS D70
			   , 0 AS D71
			   , 0 AS D72
			   , 0 AS D73
			   , 0 AS D74
			   , 0 AS D75
			   , 0 AS D76
			   , 0 AS D77
			   , 0 AS D78
			   , 0 AS D79
			   , 0 AS D80
			   , 0 AS D81
			   , 0 AS D82
			   , 0 AS D83
			   , 0 AS D84
			   , 0 AS D85
			   , 0 AS D86
			   , 0 AS D87
			   , 0 AS D88
			   , 0 AS D89
			   , 0 AS D90
			   , 0 AS D91
			   , 0 AS D92
			   , 0 AS D93
			   , 0 AS D94
			   , 0 AS D95
			   , 0 AS D96
			   , 0 AS D97
			   , 0 AS D98
			   , 0 AS D99
			   , 0 AS D100
        	   , B.CATEGORY_ID
               , B.CATEGORY_ORDER
        	   , B.MEASURE_ID, B.MEASURE_NAME
               , NULL AS S_ROW
          FROM   (
          			SELECT AAA.INSTANCE_ID, AAA.FP_PLAN_ID, AAA.COMPANY_ID, AAA.DIVISION_ID, AAA.SITE_ID, AAA.PLANT_ID
							, AAA.TOP_ITEM_ID, AAA.ITEM_ID, AAA.ITEM_TYPE, AAA.NICK_NAME
							, AAA.OPERATION_ID
							, AAA.FACTORY_ID, AAA.LOCATION
							, AAA.QTY
					FROM (
								              SELECT AA.INSTANCE_ID, AA.FP_PLAN_ID, AA.COMPANY_ID, AA.DIVISION_ID, AA.SITE_ID, AA.PLANT_ID
								                   , AA.TOP_ITEM_ID, AA.ITEM_ID, AA.ITEM_TYPE, AA.NICK_NAME
								                   , AA.OPERATION_ID
								                   , AA.FACTORY_ID, AA.LOCATION
								                   , D.QTY
								              FROM (
										                 SELECT  A.INSTANCE_ID, A.FP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID
										                       , A.TOP_ITEM_ID, A.ITEM_ID, MAX(ISNULL((CASE WHEN LEFT(B.FLOW_ID,5) = 'A9000' AND ISNULL(D.LEVEL_4_NAME, '-') = '-' THEN D.LEVEL_3_NAME
												                     	     WHEN LEFT(B.FLOW_ID,5) = 'A9000' THEN ISNULL(D.LEVEL_4_NAME, '-')
												                     	     ELSE D.LEVEL_3_NAME END),'-')) AS ITEM_TYPE, MAX(ISNULL(C.NICK_NAME,'-')) AS NICK_NAME
										                       , A.OPERATION_ID
										                       , A.FACTORY_ID, A.LOCATION
										                  FROM (
										                      SELECT A.INSTANCE_ID, A.FP_PLAN_ID
										                           , A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID
										                           , A.TOP_ITEM_ID, A.ITEM_ID, NULL ITEM_TYPE
										                           , A.OPERATION_ID
										                           , A.FACTORY_ID, A.LOCATION
										                           , NULL AS BOH_QTY
										                           , A.PRODUCTION_TYPE, A.MARKET
										                           , 'I' AS PSI
										                           , A.LINE_ID
										                           , A.ELECTRODE_TYPE
										                      FROM   FP_AMEND_PLAN_CELL_R A WITH(NOLOCK)
																	,SCM_SYS_LOOKUP_VALUE SLV WITH(NOLOCK)  -- 2021-04-22 kimcd production type 조건 추가
										                      WHERE  ( A.OUT_QTY <> 0 OR A.RESULT_OUT_QTY <> 0 OR A.WPP_OUT_QTY <> 0 ) -- 2019-09-26 kimcd "OR A.WPP_OUT_QTY <> 0"  조건 추가
																AND  A.DIVISION_ID = SLV.SEGMENT1
																AND  A.PRODUCTION_TYPE = SLV.ATTRIBUTE2
																AND  SLV.LOOKUP_TYPE_CODE = 'DIVISION_DEMAND_TYPE'
																AND  SLV.ACTIVE_FLAG = 'Y'
										                      UNION ALL
												            SELECT A.INSTANCE_ID, A.FP_PLAN_ID
												                , A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID
												                , A.TOP_ITEM_ID, A.ITEM_ID, NULL ITEM_TYPE
												                , A.OPERATION_ID
												                , A.FACTORY_ID, A.LOCATION
												                , NULL AS BOH_QTY
												                , A.PRODUCTION_TYPE, A.MARKET
												                , 'I' AS PSI
												                , A.LINE_ID
												                , A.ELECTRODE_TYPE
												            FROM   FP_AMEND_PLAN_CELL_SALES_R A WITH(NOLOCK)
								                  ) A
								                  INNER JOIN SCM_ITEM_M B WITH(NOLOCK)
	  										          ON  A.COMPANY_ID  = B.COMPANY_ID
													  AND A.DIVISION_ID = B.DIVISION_ID
													  AND A.SITE_ID     = B.SITE_ID
													  AND A.ITEM_ID     = B.ITEM_ID
													  INNER JOIN SCM_ITEM_CLASS_M D WITH(NOLOCK)
												          ON	 B.ITEM_CLASS  = D.CLASS_ID
								                  INNER JOIN SCM_ITEM_M C WITH(NOLOCK)
								                  ON     A.COMPANY_ID   = C.COMPANY_ID
								                  AND    A.DIVISION_ID  = C.DIVISION_ID
								                  AND    A.SITE_ID      = C.SITE_ID
								                  AND    A.TOP_ITEM_ID  = C.ITEM_ID
								                  GROUP BY A.INSTANCE_ID, A.FP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID
								                         , A.TOP_ITEM_ID, A.ITEM_ID, A.OPERATION_ID, A.FACTORY_ID, A.LOCATION
						              ) AA
						              LEFT OUTER JOIN (
							                  SELECT A.INSTANCE_ID, A.FP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID
								                   , A.OPERATION_ID, A.LOCATION
								                   , A.ITEM_ID, A.TOP_ITEM_ID, SUM(ISNULL(A.MODIFY_QTY, A.QTY)) AS QTY -- FLOOR(SUM(ISNULL(A.MODIFY_QTY, A.QTY))  * ISNULL(DBO.FN_GET_REQ_QTY_MODEL(A.PLANT_ID, A.TOP_ITEM_ID, A.ITEM_ID, SUBSTRING(REPLACE(A.FP_PLAN_ID , A.INSTANCE_ID , '') , 2,8)),1))		AS QTY -- 2019-09-19 songhs Cell 환산 로직추가 
								              FROM   FP_AMEND_CUTOFF_BOH_R A WITH(NOLOCK)
							                  GROUP BY A.INSTANCE_ID, A.FP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID, A.FACTORY_ID
							                         , A.OPERATION_ID, A.LOCATION, A.ITEM_ID, A.TOP_ITEM_ID
						              ) D
						              ON     AA.INSTANCE_ID  = D.INSTANCE_ID
						              AND    AA.FP_PLAN_ID   = D.FP_PLAN_ID
						              AND    AA.COMPANY_ID   = D.COMPANY_ID
						              AND    AA.DIVISION_ID  = D.DIVISION_ID
						              AND    AA.SITE_ID      = D.SITE_ID
						              AND    AA.PLANT_ID     = D.PLANT_ID
						              AND    AA.FACTORY_ID   = D.FACTORY_ID
						              AND    AA.OPERATION_ID = D.OPERATION_ID
						              AND    AA.LOCATION     = D.LOCATION
						              AND    AA.ITEM_ID      = D.ITEM_ID
						              AND    AA.TOP_ITEM_ID  = D.TOP_ITEM_ID
					) AAA
					WHERE 1=1
          ) A
          INNER JOIN (
          				SELECT 'I' AS CATEGORY_ID, 'I' AS CATEGORY_NAME, 50 AS CATEGORY_ORDER, 'UOM' AS MEASURE_ID, 'UOM' AS MEASURE_NAME
        				UNION ALL
        				SELECT 'I_CELL' AS CATEGORY_ID, 'I' AS CATEGORY_NAME, 40 AS CATEGORY_ORDER, 'CELL' AS MEASURE_ID, 'CELL' AS MEASURE_NAME
    	             ) B
			ON 1=1
          GROUP BY A.INSTANCE_ID, A.FP_PLAN_ID, A.COMPANY_ID, A.DIVISION_ID, A.SITE_ID, A.PLANT_ID
                 , A.TOP_ITEM_ID, A.ITEM_ID, A.ITEM_TYPE
                 , A.OPERATION_ID, A.FACTORY_ID, A.LOCATION
                 , B.CATEGORY_NAME
                 , B.CATEGORY_ID
                 , B.CATEGORY_ORDER
                 , B.MEASURE_ID, B.MEASURE_NAME
      )
